I'll show you a React example with debounce, since that's the most common pattern. Here are the main approaches:

## 1. Using a custom hook (recommended)

```javascript
import { useState, useRef, useCallback } from 'react';

const useDebounce = (callback, delay) => {
  const timeoutRef = useRef(null);

  return useCallback((...args) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callback(...args), delay);
  }, [callback, delay]);
};

export function SearchInput() {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchResults = async (query) => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    setLoading(true);
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    const data = await res.json();
    setResults(data);
    setLoading(false);
  };

  const debouncedSearch = useDebounce(fetchResults, 300);

  const handleChange = (e) => {
    debouncedSearch(e.target.value);
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        onChange={handleChange}
      />
      {loading && <p>Loading...</p>}
      <ul>
        {results.map(item => <li key={item.id}>{item.name}</li>)}
      </ul>
    </div>
  );
}
```

## 2. Using lodash (simplest)

```javascript
import { debounce } from 'lodash-es';
import { useState } from 'react';

export function SearchInput() {
  const [results, setResults] = useState([]);

  const fetchResults = debounce(async (query) => {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    setResults(await res.json());
  }, 300);

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        onChange={(e) => fetchResults(e.target.value)}
      />
      <ul>
        {results.map(item => <li key={item.id}>{item.name}</li>)}
      </ul>
    </div>
  );
}
```

## 3. Vanilla JavaScript

```javascript
function createSearchInput() {
  const input = document.querySelector('#search');
  const resultsList = document.querySelector('#results');
  let timeoutId;

  async function fetchResults(query) {
    if (!query.trim()) {
      resultsList.innerHTML = '';
      return;
    }
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    const data = await res.json();
    resultsList.innerHTML = data
      .map(item => `<li>${item.name}</li>`)
      .join('');
  }

  input.addEventListener('input', (e) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fetchResults(e.target.value), 300);
  });
}
```

**Key points:**
- **300ms delay** is typical for search (adjust based on your API latency)
- **clearTimeout** cancels previous requests if user types before delay expires
- **Custom hook** approach is most reusable and testable
- Add error handling and cleanup as needed for production

